// P1 防御：校验 webhook 静态密钥（?secret=）。失败直接丢弃。
const expected = (typeof $vars !== 'undefined' && $vars && $vars.webhook_secret) ? $vars.webhook_secret : '';
const q = ($input.item.json && $input.item.json.query) || {};
const got = q.secret || '';
if (!(expected && got && got === expected)) {
  return [];
}
return $input.all();

