// ezB 列表响应为 {success,result:[...]}，兼容直接返回数组的情况
const r = $input.first().json;
const list = Array.isArray(r) ? r : (r && r.result) || [];
return (list || []).map(t => ({ json: t }));

// P2 自动打标：对缺少 #recur-<标识> 的周期交易模板，按「模板名」推导标识并写入备注。
// 约定：ezB 周期交易名称即 recur 标识（仅保留 中文/字母/数字/_/-），
// 对应 Vikunja 任务的标签为 recur-<标识>（如 ezB 名「房贷01」→ 标签 recur-房贷01）。
// 若备注已含 #recur-，则保留（用户自定义 / 已打标），不覆盖。
const out = [];
for (const t of $input.all()) {
  const item = t.json;
  const existing = (item.comment || '');
  if (/#recur-[^#\s]+/.test(existing)) continue; // 已打标，跳过
  const name = (item.name || '').trim();
  const token = name.replace(/[^\p{L}\p{N}_-]/gu, '');
  if (!token) continue; // 无可用名称则跳过
  const newComment = (existing ? existing + ' ' : '') + '#recur-' + token;
  const comment = newComment.slice(0, 255); // ezB comment 上限 255
  const body = {
    id: String(item.id),
    name: item.name,
    type: item.type,
    categoryId: String(item.categoryId),
    sourceAccountId: String(item.sourceAccountId),
    destinationAccountId: String(item.destinationAccountId || 0),
    sourceAmount: item.sourceAmount,
    destinationAmount: item.destinationAmount || 0,
    hideAmount: !!item.hideAmount,
    tagIds: item.tagIds || [],
    comment: comment,
    scheduledFrequencyType: item.scheduledFrequencyType,
    scheduledFrequency: item.scheduledFrequency || null,
    scheduledStartDate: item.scheduledStartDate || null,
    scheduledEndDate: item.scheduledEndDate || null,
    utcOffset: item.utcOffset
  };
  out.push({ json: { templateId: item.id, name: item.name, token: token, comment: comment, modifyBody: body } });
}
return out;

const items = $input.all();
const tagged = items.map(i => ({ token: i.json.token, name: i.json.name, comment: i.json.comment }));
return [{ json: { status: 'done', taggedCount: tagged.length, tagged: tagged } }];
